'use strict';
/* BLOCK CITY TYCOON — ADMIN WORLD BUILDER 2.0 · TOOLS (Part 19)
   175 admin tools in 11 categories (World, Terrain, Water, Roads, City, Buildings, Utilities, Population, Economy,
   Environment, Transportation, Disaster / Emergency, Debug / Development). Every tool runs real game code; there are
   no placeholder buttons. Tools act on the TARGET (the selected building, otherwise the tile at the camera centre) with
   an optional VALUE. Mutating tools snapshot the city first → Ctrl+Z / Ctrl+Y undo / redo (in memory, last 10 steps;
   the persistent Snapshot Manager stays available). Search (also in the admin search and the Ctrl+K palette) and
   favourites. Every call goes through AdminAuth.guard (adminWrap('adminTool')): a normal player never sees or runs them. */

const AT = { q: '', out: '', undo: [], redo: [], max: 10, open: {}, last: null };
const AT_CATS = [['world', '🌍', 'World'], ['terrain', '⛰️', 'Terrain'], ['water', '💧', 'Water'], ['roads', '🛣️', 'Roads'], ['city', '🏙️', 'City'], ['buildings', '🏢', 'Buildings'], ['utilities', '⚡', 'Utilities'], ['population', '👥', 'Population'], ['economy', '💰', 'Economy'], ['environment', '🌿', 'Environment'], ['transport', '🚇', 'Transportation'], ['disaster', '🚨', 'Disaster / Emergency'], ['debug', '🔧', 'Debug / Development']];
const AT_TOOLS = [];
/* id, cat, name, kind ('mut' undoable · 'view' read-only · 'gen' world creation · 'del' destructive), run(v, t) → text, keywords */
function atDef(id, cat, name, kind, run, kw) { AT_TOOLS.push({ id: id, cat: cat, name: name, kind: kind, run: run, kw: (kw || '').toLowerCase() }); }
function atTool(id) { return AT_TOOLS.find(function (t) { return t.id === id; }); }

/* ---------- target & helpers ---------- */
function atTarget() {
  const b = UI.selected && UI.selected.type && MAP.byId.get(UI.selected.id) ? UI.selected : null;
  if (b) return { x: b.x, y: b.y, b: b, tile: idx(b.x, b.y) };
  const x = clamp(Math.floor(CAM.x / TILE), 0, MAP.W - 1), y = clamp(Math.floor(CAM.y / TILE), 0, MAP.H - 1);
  return { x: x, y: y, b: buildingAtTile(x, y), tile: idx(x, y) };
}
function atNum(v, d, lo, hi) { const n = parseFloat(v); return clamp(isFinite(n) ? n : d, lo, hi); }
function atDisk(t, r, fn) { let n = 0; for (let y = t.y - r; y <= t.y + r; y++) for (let x = t.x - r; x <= t.x + r; x++) { if (!inMap(x, y) || Math.hypot(x - t.x, y - t.y) > r + 0.3) continue; if (fn(idx(x, y), x, y, Math.hypot(x - t.x, y - t.y)) !== false) n++; } return n; }
function atFree(i) { return !MAP.occ[i] && !MAP.roads[i]; }
function atTerr(i, v) { if (MAP.nature[i] === 2) return false; MAP.terrain[i] = v; if (v === TERRAIN.ROCK && MAP.nature[i] === 1) MAP.nature[i] = 0; return true; }
function atWater(i, on) { if (on) { if (MAP.occ[i]) return false; MAP.nature[i] = 2; MAP.terrain[i] = TERRAIN.WATER; MAP.zone[i] = 0; return true; } if (MAP.nature[i] !== 2) return false; MAP.nature[i] = 0; MAP.terrain[i] = TERRAIN.SAND; return true; }
function atMapChanged() { MAP.groundDirty = true; if (typeof computeSea === 'function') computeSea(); onMapChanged(); MAP.pathCache.clear(); if (typeof envReset === 'function') envReset(); }
function atPlace(type, t, r) { const b = typeof tpPlaceNear === 'function' ? tpPlaceNear(type, t.x, t.y, r || 8) : null; if (b) onMapChanged(); return b; }
function atRoadLine(t, len, kind, filter) {
  const tiles = []; let x = t.x, y = t.y, dx = 1, dy = 0;
  if (MAP.roads[idx(x, y)]) { if (inMap(x + 1, y) && MAP.roads[idx(x + 1, y)]) { dx = 0; dy = 1; } }
  for (let k = 0; k < len; k++) { if (!inMap(x, y)) break; const i = idx(x, y); if (!MAP.occ[i] && (!filter || filter(i))) { MAP.roads[i] = kind; tiles.push(i); } else if (MAP.occ[i]) break; x += dx; y += dy; }
  atMapChanged(); return tiles.length;
}
function atLines() { return S.p9 ? S.p9.transit.lines : []; }
function atJunction(t) { if (MAP.inter[t.tile]) return t.tile; for (let r = 1; r <= 4; r++) for (let y = t.y - r; y <= t.y + r; y++) for (let x = t.x - r; x <= t.x + r; x++) if (inMap(x, y) && MAP.inter[idx(x, y)]) return idx(x, y); return -1; }
function atReport(o) { return Object.keys(o).map(function (k) { return k + ': ' + (typeof o[k] === 'number' ? Math.round(o[k] * 100) / 100 : o[k]); }).join('\n'); }
const ATMODS = { power: 1, water: 1, wage: 1, gdp: 1 };
(function () { const gm = window.globalMods; if (typeof gm === 'function' && !gm.__p19at) { window.globalMods = function () { const m = gm.apply(this, arguments); if (S && S.adminTools) { const A = S.adminTools; m.powerDemand *= A.power || 1; m.waterUse *= A.water || 1; m.wage = (m.wage || 1) * (A.wage || 1); m.rev *= A.gdp || 1; } return m; }; window.globalMods.__p19at = true; } })();
function atMods() { if (!S.adminTools) S.adminTools = { power: 1, water: 1, wage: 1, gdp: 1 }; return S.adminTools; }

/* ---------- WORLD (20) ---------- */
atDef('createWorld', 'world', 'Create World', 'gen', function (v) { const pr = WORLD_PRESETS[v] ? v : (ADM.wgPreset || 'balanced'); wbCreateOptimizedWorld(pr, WBLD.profile, { size: ADM.wgSize !== 'AUTO' ? ADM.wgSize : undefined, seed: ADM.wgSeed || undefined }); return 'Generating an optimized ' + pr + ' world (profile ' + WBLD.profile + ')…'; }, 'new generate world optimized');
atDef('deleteWorld', 'world', 'Delete World', 'del', function (v) { const slot = atNum(v, 0, 0, 20) | 0; if (!slot || slot === S.slot) return 'Give the number of ANOTHER save slot to delete (current slot ' + S.slot + ' cannot be deleted while it is open).'; const k = typeof slotKey === 'function' ? slotKey(slot) : null; if (!k || !Store.getItem(k)) return 'Slot ' + slot + ' is empty.'; Store.removeItem(k); return 'Save slot ' + slot + ' deleted.'; }, 'remove slot');
atDef('cloneWorld', 'world', 'Clone World', 'mut', function (v) { const r = cloneWorld(v || S.city.name + ' Clone', 0); return r && r.ok === false ? r.reason : 'World cloned into a free slot.'; }, 'copy');
atDef('duplicateWorld', 'world', 'Duplicate World', 'mut', function () { adminDo('duplicate'); return 'World duplicated (Snapshot + slot copy).'; }, 'copy');
atDef('renameWorld', 'world', 'Rename World', 'mut', function (v) { const n = String(v || '').replace(/[<>]/g, '').trim().slice(0, 32); if (!n) return 'Enter the new name in VALUE.'; S.city.name = n; if (typeof refreshTopbar === 'function') refreshTopbar(); return 'City renamed to ' + n; }, 'name');
atDef('changeSeed', 'world', 'Change Seed', 'view', function (v) { const s = v ? parseSeed(v) : Math.floor(Math.random() * 1e6); ADM.wgSeed = String(s); return 'Next world will use seed ' + seedLabel(s) + ' (current world: ' + seedLabel() + ').'; }, 'seed random');
atDef('regenerateWorld', 'world', 'Regenerate World', 'gen', function () { const W = S.p8.world || {}; wbCreateOptimizedWorld(W.preset || 'balanced', (S.worldbuilder && S.worldbuilder.profile) || WBLD.profile, { seed: W.seed, size: W.sizeName }); return 'Regenerating the same world (seed ' + seedLabel(W.seed) + ')…'; }, 'reset same seed');
atDef('regenTerrain', 'world', 'Regenerate Terrain', 'mut', function () { const rnd = mulberry32((S.city.seed || 1) * 7 + Date.now() % 9973); let n = 0; for (let i = 0; i < MAP.W * MAP.H; i++) { if (!atFree(i) || MAP.nature[i] === 2 || MAP.zone[i]) continue; const r = rnd(); MAP.terrain[i] = r < 0.12 ? TERRAIN.HILL : r < 0.15 ? TERRAIN.ROCK : TERRAIN.GRASS; n++; } atMapChanged(); return n + ' empty tiles re-shaped (buildings, roads and zones untouched).'; }, 'hills rock');
atDef('regenDistricts', 'world', 'Regenerate Districts', 'mut', function () { computeDistricts(); computeDistrictNames(); if (typeof govDistrictsHour === 'function' && S.government) govDistrictsHour(); return (MAP.districts || []).length + ' district cells recomputed and renamed.'; }, 'names');
atDef('regenRoads', 'world', 'Regenerate Roads', 'mut', function () { const j = wgConnectRoads(); let sp = 0; S.buildings.list.forEach(function (b) { const d = bdef(b); if (!d.noRoad && b._entry < 0 && wgSpurRoad(b.x, b.y, d)) sp++; }); JX.types.clear(); atMapChanged(); return (j || 0) + ' connector(s) · ' + sp + ' access road(s) · junction types recomputed.'; }, 'connect');
atDef('regenBuildings', 'world', 'Regenerate Buildings', 'mut', function () { const r = fixWorld(true); return r.actions.join('\n'); }, 'fill housing jobs');
atDef('regenPopulation', 'world', 'Regenerate Population', 'mut', function () { resetAgents(); econTick(1); const target = Math.round((SIM.housingCap || 0) * 0.92); admSetPop(target); return 'Citizen agents respawned · population set to 92% of housing (' + fmt(target) + ').'; }, 'citizens');
atDef('regenEconomy', 'world', 'Regenerate Economy', 'mut', function () { const r = fixEconomy(); if (S.p17) { E2.hourKey = -1; part17Tick(); } return r; }, 'money budget');
atDef('regenTransport', 'world', 'Regenerate Transportation', 'mut', function () { const r = tpGenerateTransport(); return r.ok ? r.list.map(function (s) { return s[0] + ': ' + s[1]; }).join('\n') : r.reason; }, 'transit metro bus generate transportation');
atDef('worldValidator', 'world', 'World Validator', 'view', function () { const a = wbAnalyzeCurrent(); return WB_TESTS.map(function (x) { const t = a.v.tests[x[0]]; return (t.ok ? '✓ ' : '✗ ') + x[1] + ' — ' + t.detail; }).join('\n') + '\n→ ' + (a.q.ready ? 'WORLD READY' : 'NOT READY: ' + a.q.broken.join(', ')); }, 'validate check golden rule');
atDef('autoFixWorld', 'world', 'Auto Fix World', 'mut', function () { const r = wbAutoFixCurrent(); return r.passes + ' pass(es) · ' + r.fixes.length + ' fix(es)\n' + r.fixes.join('\n') + '\n→ quality ' + r.q.overall + '% ' + r.q.label + (r.q.ready ? ' · WORLD READY' : ' · NOT READY'); }, 'repair fix');
atDef('balanceWorld', 'world', 'Balance World', 'mut', function () { const b = wbBalanceEnvironment(null, wbProfileFor((S.worldbuilder && S.worldbuilder.cfg) || {})); const e = fixEconomy(); return atReport(b.metrics) + '\nrelocated ' + b.log.moved + ' · trees ' + b.log.trees + ' · parks ' + b.log.parks + '\n' + e; }, 'pollution balance');
atDef('optimizeWorld', 'world', 'Optimize World', 'mut', function () { MAP.pathCache.clear(); const f = S.p9 ? fixTraffic() : ''; const t = tp3AutoFix(); const pq = perf(); let k = 0; while (AG.vehicles.length > pq.veh * 2) { AG.vehicles.pop(); k++; } return f + '\n' + t.actions.length + ' transport fix(es) · ' + k + ' surplus vehicle(s) removed · path cache cleared'; }, 'performance traffic');
atDef('worldQuality', 'world', 'World Quality Score', 'view', function () { const a = wbAnalyzeCurrent(); return 'WORLD QUALITY ' + a.q.overall + '% — ' + a.q.label + '\n' + Object.keys(a.q.cats).map(function (k) { return k + ': ' + a.q.cats[k]; }).join('\n'); }, 'score');
atDef('worldSnapshot', 'world', 'World Snapshot', 'view', function (v) { const m = createSnapshot(v || 'Admin snapshot', true); return m ? 'Snapshot ' + m.id + ' saved.' : 'Snapshot failed (storage full?).'; }, 'save backup');

/* ---------- TERRAIN (15) ---------- */
const AT_UP = { 0: TERRAIN.HILL, 4: TERRAIN.GRASS, 2: TERRAIN.ROCK, 3: TERRAIN.ROCK }, AT_DOWN = { 3: TERRAIN.HILL, 2: TERRAIN.GRASS, 0: TERRAIN.SAND, 4: TERRAIN.SAND };
atDef('raiseTerrain', 'terrain', 'Raise Terrain', 'mut', function (v, t) { const n = atDisk(t, atNum(v, 3, 1, 12), function (i) { if (!atFree(i)) return false; return atTerr(i, AT_UP[MAP.terrain[i]] !== undefined ? AT_UP[MAP.terrain[i]] : TERRAIN.HILL); }); atMapChanged(); return n + ' tiles raised around ' + t.x + ',' + t.y; }, 'height up');
atDef('lowerTerrain', 'terrain', 'Lower Terrain', 'mut', function (v, t) { const n = atDisk(t, atNum(v, 3, 1, 12), function (i) { if (!atFree(i)) return false; return atTerr(i, AT_DOWN[MAP.terrain[i]] !== undefined ? AT_DOWN[MAP.terrain[i]] : TERRAIN.GRASS); }); atMapChanged(); return n + ' tiles lowered'; }, 'height down');
atDef('flattenTerrain', 'terrain', 'Flatten Terrain', 'mut', function (v, t) { const n = atDisk(t, atNum(v, 4, 1, 16), function (i) { return MAP.terrain[i] !== TERRAIN.GRASS && !MAP.occ[i] ? atTerr(i, TERRAIN.GRASS) : false; }); atMapChanged(); return n + ' tiles flattened to grass'; }, 'level');
atDef('smoothTerrain', 'terrain', 'Smooth Terrain', 'mut', function (v, t) { const r = atNum(v, 5, 1, 16), copy = MAP.terrain.slice(); let n = 0; atDisk(t, r, function (i, x, y) { if (!atFree(i) || MAP.nature[i] === 2) return false; const cnt = {}; for (let yy = y - 1; yy <= y + 1; yy++) for (let xx = x - 1; xx <= x + 1; xx++) if (inMap(xx, yy)) { const c = copy[idx(xx, yy)]; cnt[c] = (cnt[c] || 0) + 1; } const best = +Object.keys(cnt).sort(function (a, b) { return cnt[b] - cnt[a]; })[0]; if (best !== MAP.terrain[i] && best !== TERRAIN.WATER) { MAP.terrain[i] = best; n++; } }); atMapChanged(); return n + ' tiles smoothed'; }, 'blur');
atDef('createMountain', 'terrain', 'Create Mountain', 'mut', function (v, t) { const r = atNum(v, 4, 2, 12); const n = atDisk(t, r, function (i, x, y, d) { if (!atFree(i)) return false; return atTerr(i, d < r * 0.45 ? TERRAIN.ROCK : TERRAIN.HILL); }); atMapChanged(); return 'Mountain: ' + n + ' tiles (rock peak, hills around)'; }, 'peak rock');
atDef('createHill', 'terrain', 'Create Hill', 'mut', function (v, t) { const n = atDisk(t, atNum(v, 3, 1, 10), function (i) { return atFree(i) ? atTerr(i, TERRAIN.HILL) : false; }); atMapChanged(); return 'Hill: ' + n + ' tiles'; });
atDef('createValley', 'terrain', 'Create Valley', 'mut', function (v, t) { const r = atNum(v, 5, 2, 14); const n = atDisk(t, r, function (i, x, y, d) { if (!atFree(i)) return false; return atTerr(i, d < r * 0.6 ? TERRAIN.GRASS : TERRAIN.HILL); }); atMapChanged(); return 'Valley: ' + n + ' tiles (flat floor, hills on the rim)'; });
atDef('createRiver', 'terrain', 'Create River', 'mut', function (v, t) { const len = atNum(v, MAP.W, 4, MAP.W * 2); let x = t.x, y = t.y, n = 0; const rnd = mulberry32(t.tile + 17); for (let k = 0; k < len && inMap(x, y); k++) { const i = idx(x, y); if (!MAP.occ[i] && atWater(i, true)) n++; if (rnd() < 0.7) x++; else y += rnd() < 0.5 ? 1 : -1; } atMapChanged(); return 'River: ' + n + ' water tiles (existing roads became bridges, buildings kept)'; }, 'water');
atDef('createLake', 'terrain', 'Create Lake', 'mut', function (v, t) { const n = atDisk(t, atNum(v, 3, 1, 10), function (i) { return atFree(i) ? atWater(i, true) : false; }); atMapChanged(); return 'Lake: ' + n + ' water tiles'; }, 'water');
atDef('createCoast', 'terrain', 'Create Coast', 'mut', function (v) { const w = atNum(v, 3, 1, 10) | 0; let n = 0; for (let y = 0; y < MAP.H; y++) for (let x = 0; x < w; x++) { const i = idx(x, y); if (atFree(i) && atWater(i, true)) n++; } atMapChanged(); return 'Coast: ' + n + ' sea tiles on the west edge'; }, 'sea');
atDef('createIsland', 'terrain', 'Create Island', 'mut', function (v, t) { const r = atNum(v, 6, 3, 16); const n = atDisk(t, r + 2, function (i, x, y, d) { return d > r && atFree(i) ? atWater(i, true) : false; }); atMapChanged(); return 'Island: a ring of ' + n + ' water tiles around radius ' + r; });
atDef('createCanyon', 'terrain', 'Create Canyon', 'mut', function (v, t) { const len = atNum(v, 16, 4, 64) | 0; let n = 0; for (let k = 0; k < len; k++) { const x = t.x + k; [[0, TERRAIN.GRASS], [-1, TERRAIN.ROCK], [1, TERRAIN.ROCK], [-2, TERRAIN.HILL], [2, TERRAIN.HILL]].forEach(function (o) { const y = t.y + o[0]; if (inMap(x, y) && atFree(idx(x, y)) && atTerr(idx(x, y), o[1])) n++; }); } atMapChanged(); return 'Canyon: ' + n + ' tiles'; });
atDef('terrainNoise', 'terrain', 'Terrain Noise Control', 'mut', function (v, t) { const s = atNum(v, 0.2, 0.02, 0.6), rnd = mulberry32(t.tile * 31 + 5); const n = atDisk(t, 10, function (i) { if (!atFree(i) || MAP.nature[i] === 2 || rnd() > s) return false; return atTerr(i, rnd() < 0.7 ? TERRAIN.HILL : TERRAIN.GRASS); }); atMapChanged(); return 'Noise ' + s + ': ' + n + ' tiles varied within 10 tiles'; }, 'roughness');
atDef('terrainHeightMap', 'terrain', 'Terrain Height Map', 'view', function () { setHeatmap('ELEVATION'); let c = { grass: 0, hill: 0, rock: 0, sand: 0, water: 0 }; for (let i = 0; i < MAP.W * MAP.H; i++) { if (MAP.nature[i] === 2) c.water++; else if (MAP.terrain[i] === TERRAIN.HILL) c.hill++; else if (MAP.terrain[i] === TERRAIN.ROCK) c.rock++; else if (MAP.terrain[i] === TERRAIN.SAND) c.sand++; else c.grass++; } return 'Elevation heatmap on.\n' + atReport(c); }, 'elevation heatmap');
atDef('terrainUndo', 'terrain', 'Terrain Undo', 'view', function () { return atUndo(); }, 'undo');

/* ---------- WATER (10) ---------- */
atDef('createWater', 'water', 'Create Water', 'mut', function (v, t) { const n = atDisk(t, atNum(v, 1, 0, 6), function (i) { return atFree(i) ? atWater(i, true) : false; }); atMapChanged(); return n + ' water tile(s)'; });
atDef('removeWater', 'water', 'Remove Water', 'mut', function (v, t) { const n = atDisk(t, atNum(v, 2, 0, 10), function (i) { return MAP.nature[i] === 2 && !MAP.roads[i] ? atWater(i, false) : false; }); atMapChanged(); return n + ' water tile(s) turned into land'; }, 'drain');
atDef('waterLevel', 'water', 'Change Water Level', 'mut', function (v, t) { const up = atNum(v, 1, -3, 3) >= 0, copy = MAP.nature.slice(); const n = atDisk(t, 12, function (i, x, y) { const near = [[1, 0], [-1, 0], [0, 1], [0, -1]].some(function (o) { return inMap(x + o[0], y + o[1]) && copy[idx(x + o[0], y + o[1])] === 2; }); if (up) return copy[i] !== 2 && near && atFree(i) ? atWater(i, true) : false; return copy[i] === 2 && [[1, 0], [-1, 0], [0, 1], [0, -1]].some(function (o) { return inMap(x + o[0], y + o[1]) && copy[idx(x + o[0], y + o[1])] !== 2; }) && !MAP.roads[i] ? atWater(i, false) : false; }); atMapChanged(); return 'Water level ' + (up ? 'raised' : 'lowered') + ': ' + n + ' shore tiles changed'; }, 'flood shore');
atDef('riverGen', 'water', 'River Generator', 'mut', function () { const rnd = mulberry32((S.city.seed || 3) * 13 + AT_TOOLS.length); let y = Math.floor(MAP.H * (0.2 + rnd() * 0.6)), n = 0; for (let x = 0; x < MAP.W; x++) { for (let w = 0; w < 2; w++) { const yy = y + w; if (inMap(x, yy) && atFree(idx(x, yy)) && atWater(idx(x, yy), true)) n++; } if (rnd() < 0.3) y = clamp(y + (rnd() < 0.5 ? 1 : -1), 1, MAP.H - 3); } atMapChanged(); return 'River across the map: ' + n + ' water tiles (around buildings and roads)'; });
atDef('lakeGen', 'water', 'Lake Generator', 'mut', function () { const rnd = mulberry32((S.city.seed || 5) * 29 + Date.now() % 997); for (let k = 0; k < 80; k++) { const x = Math.floor(rnd() * MAP.W), y = Math.floor(rnd() * MAP.H); let free = 0; atDisk({ x: x, y: y }, 3, function (i) { if (atFree(i)) free++; return false; }); if (free >= 24) { const n = atDisk({ x: x, y: y }, 3, function (i) { return atFree(i) ? atWater(i, true) : false; }); atMapChanged(); return 'Lake of ' + n + ' tiles at ' + x + ',' + y; } } return 'No free area for a lake.'; });
atDef('coastGen', 'water', 'Coast Generator', 'mut', function (v) { const side = ['west', 'east', 'north', 'south'].indexOf(String(v || 'south').toLowerCase()); let n = 0; for (let k = 0; k < Math.max(MAP.W, MAP.H); k++) for (let w = 0; w < 3; w++) { const p = [[w, k], [MAP.W - 1 - w, k], [k, w], [k, MAP.H - 1 - w]][side < 0 ? 3 : side]; if (inMap(p[0], p[1]) && atFree(idx(p[0], p[1])) && atWater(idx(p[0], p[1]), true)) n++; } atMapChanged(); return 'Coast (' + (side < 0 ? 'south' : ['west', 'east', 'north', 'south'][side]) + '): ' + n + ' sea tiles'; }, 'sea west east north south');
atDef('waterQuality', 'water', 'Water Quality Editor', 'mut', function (v, t) { if (!ENV.water) envTick(true); const q = atNum(v, 95, 0, 100) / 100; const n = atDisk(t, 10, function (i) { if (MAP.nature[i] !== 2) return false; ENV.water[i] = q; }); return n + ' water tiles set to ' + Math.round(q * 100) + '% quality'; }, 'clean');
atDef('waterPollution', 'water', 'Water Pollution Editor', 'mut', function (v, t) { if (!ENV.water) envTick(true); const p = atNum(v, 40, 0, 100) / 100; const n = atDisk(t, 10, function (i) { if (MAP.nature[i] !== 2) return false; ENV.water[i] = clamp(1 - p, 0, 1); }); return n + ' water tiles polluted to ' + Math.round(p * 100) + '%'; }, 'dirty');
atDef('waterFlow', 'water', 'Water Flow Debugger', 'view', function () { const W = typeof WNET !== 'undefined' ? WNET : {}; return atReport({ 'water produced': SIM.waterGen || 0, 'water used': SIM.waterUse || 0, 'supply ratio': SIM.waterRatio || 0, 'low pressure share': W.low || 0, 'pipe breaks': S.p9 && S.p9.water ? (S.p9.water.breaks || []).length : 0, 'sewage overload': typeof SEWER !== 'undefined' ? SEWER.overload || 0 : 0 }); }, 'pressure pipes');
atDef('floodRisk', 'water', 'Flood Risk Editor', 'mut', function (v, t) { let low = 0; atDisk(t, 8, function (i, x, y) { if (MAP.nature[i] !== 2 && [[1, 0], [-1, 0], [0, 1], [0, -1]].some(function (o) { return inMap(x + o[0], y + o[1]) && MAP.nature[idx(x + o[0], y + o[1])] === 2; })) low++; return false; }); if (String(v) === 'protect') { const b = atPlace('floodbarrier', t, 6); return b ? 'Flood barrier built (protects 6 tiles) · ' + low + ' shore tiles at risk nearby' : 'No shore site for a flood barrier near the target'; } return low + ' shore tiles at flood risk within 8 tiles · VALUE "protect" builds a flood barrier'; }, 'flood barrier');

/* ---------- ROADS (15) ---------- */
atDef('roadGen', 'roads', 'Road Generator', 'mut', function (v, t) { return 'Road: ' + atRoadLine(t, atNum(v, 10, 2, 64) | 0, 2, function (i) { return MAP.nature[i] !== 2; }) + ' tiles (medium road)'; }, 'street');
atDef('highwayGen', 'roads', 'Highway Generator', 'mut', function () { const tiles = corridorTiles(); tiles.forEach(function (i) { MAP.roads[i] = 4; }); atMapChanged(); return tiles.length ? 'Highway: ' + tiles.length + ' congested tiles upgraded instantly' : 'No congested corridor found'; }, 'motorway');
atDef('bridgeGen', 'roads', 'Bridge Generator', 'mut', function (v, t) { let x = t.x, y = t.y, n = 0; for (let k = 0; k < atNum(v, 12, 2, 40); k++) { if (!inMap(x, y)) break; const i = idx(x, y); if (MAP.occ[i]) break; if (!MAP.roads[i]) { MAP.roads[i] = 2; n++; } x++; } atMapChanged(); return 'Bridge / road: ' + n + ' tiles eastwards (water tiles become a bridge)'; });
atDef('tunnelGen', 'roads', 'Tunnel Generator', 'mut', function (v, t) { let n = 0; for (let k = 0; k < atNum(v, 12, 2, 40); k++) { const x = t.x + k, y = t.y; if (!inMap(x, y)) break; const i = idx(x, y); if (MAP.occ[i]) break; if (!MAP.roads[i]) { MAP.roads[i] = 2; n++; } } atMapChanged(); return 'Tunnel / road: ' + n + ' tiles (rock tiles are tunnels)'; });
atDef('roundaboutGen', 'roads', 'Roundabout Generator', 'mut', function (v, t) { const j = atJunction(t); if (j < 0) return 'No junction near the target'; setJunctionType(j, 'roundabout'); return 'Junction ' + j + ' → roundabout'; });
atDef('intersectionGen', 'roads', 'Intersection Generator', 'mut', function (v, t) { const j = atJunction(t); if (j < 0) return 'No junction near the target'; setJunctionType(j, String(v) && JUNCTION_TYPES[v] ? v : 'signal'); return 'Junction ' + j + ' → ' + (JUNCTION_TYPES[v] ? v : 'signal'); }, 'junction signal stop priority');
atDef('roadUpgrade', 'roads', 'Road Upgrade', 'mut', function (v, t) { const n = atDisk(t, atNum(v, 3, 0, 10), function (i) { if (!MAP.roads[i] || MAP.roads[i] >= 4) return false; MAP.roads[i]++; }); atMapChanged(); return n + ' road tiles upgraded one level'; });
atDef('roadRepair', 'roads', 'Road Repair', 'mut', function (v, t) { let n = 0; if (S.p10) Object.keys(S.p10.infra).forEach(function (k) { const a = S.p10.infra[k]; if (Math.abs((a.tile % MAP.W) - t.x) <= 12 && Math.abs(((a.tile / MAP.W) | 0) - t.y) <= 12) { a.cond = 100; n++; } }); const c = atDisk(t, 8, function (i) { if (!MAP.blocked[i]) return false; MAP.blocked[i] = 0; }); MAP.pathCache.clear(); return n + ' road / bridge asset(s) repaired · ' + c + ' blocked tile(s) cleared'; }, 'condition');
atDef('roadDelete', 'roads', 'Road Delete', 'mut', function (v, t) { const n = atDisk(t, atNum(v, 0, 0, 6), function (i) { if (!MAP.roads[i]) return false; MAP.roads[i] = 0; }); atMapChanged(); return n + ' road tile(s) removed (Ctrl+Z restores)'; }, 'remove bulldoze');
atDef('laneEditor', 'roads', 'Lane Editor', 'mut', function (v, t) { const k = atNum(v, 2, 1, 4) | 0; if (!MAP.roads[t.tile]) return 'The target tile is not a road'; MAP.roads[t.tile] = k; atMapChanged(); return 'Road type ' + ROAD_TYPES[k].name + ' (' + (ROAD_TYPES[k].lanes || k * 2) + ' lanes)'; }, 'lanes type');
atDef('lightEditor', 'roads', 'Traffic Light Editor', 'mut', function (v, t) { const j = atJunction(t); if (String(v) === 'all') return tpSetLightMode('all', 'smart').msg; if (j < 0) return 'No junction near the target'; const r = tpSetLightMode(j, TL_MODES[v] || v === 'auto' ? v : 'smart'); return r.ok ? r.msg : r.reason; }, 'signal fixed adaptive smart emergency');
atDef('speedLimit', 'roads', 'Speed Limit Editor', 'mut', function (v) { const k = atNum(v, 1, 0.5, 1.5); tp().traffic.speedMult = k; return 'City speed limits ×' + k + ' (all vehicles)'; }, 'speed');
atDef('roadPriority', 'roads', 'Road Priority Editor', 'mut', function (v, t) { const j = atJunction(t); if (j < 0) return 'No junction near the target'; setJunctionType(j, 'priority'); return 'Junction ' + j + ' → priority road'; });
atDef('oneWay', 'roads', 'One-Way Editor', 'mut', function (v, t) { if (!MAP.roads[t.tile]) return 'The target tile is not a road'; const dirs = { east: 1, west: 2, south: 3, north: 4, off: 0 }, d = dirs[String(v || 'east').toLowerCase()]; if (d === undefined) return 'VALUE: east / west / south / north / off'; tpSetOneWay(t.tile, d); return d ? 'One-way ' + v + ' on tile ' + t.tile : 'Two-way again'; }, 'direction');
atDef('roadValidator', 'roads', 'Road Validator', 'view', function () { const rc = mainRoadComp(); let dead = 0; for (let i = 0; i < MAP.roads.length; i++) { if (!MAP.roads[i]) continue; const x = i % MAP.W, y = (i / MAP.W) | 0; let n = 0; [[1, 0], [-1, 0], [0, 1], [0, -1]].forEach(function (o) { if (inMap(x + o[0], y + o[1]) && MAP.roads[idx(x + o[0], y + o[1])]) n++; }); if (n <= 1 && !MAP.occ[i]) dead++; } const off = S.buildings.list.filter(function (b) { return !bdef(b).noRoad && b._entry < 0; }).length; return atReport({ 'road tiles': MAP.roadCount, networks: rc.comps, 'dead ends': dead, 'buildings without road': off }); }, 'check');

/* ---------- CITY (15) ---------- */
function atZone(z) { return function (v, t) { const n = atDisk(t, atNum(v, 3, 1, 12), function (i) { if (MAP.roads[i] || MAP.nature[i] === 2 || MAP.terrain[i] === TERRAIN.ROCK) return false; MAP.zone[i] = z; }); onMapChanged(); return n + ' tiles zoned ' + ZONES.find(function (q) { return q.id === z; }).name; }; }
atDef('districtGen', 'city', 'District Generator', 'mut', function () { computeDistricts(); computeDistrictNames(); return (MAP.dnames || []).filter(Boolean).length + ' named district cells'; });
atDef('districtRename', 'city', 'District Rename', 'mut', function (v, t) { const n = String(v || '').replace(/[<>]/g, '').trim().slice(0, 28); if (!n || !MAP.dnames) return 'Enter the new district name in VALUE'; const old = districtName(t.x, t.y); let c = 0; MAP.dnames.forEach(function (nm, k) { if (nm === old) { MAP.dnames[k] = n; c++; } }); if (S.p8.world) S.p8.world.cellNames = MAP.dnames.slice(); return '"' + old + '" → "' + n + '" (' + c + ' cells)'; }, 'name');
atDef('districtResize', 'city', 'District Resize', 'mut', function (v, t) { const k0 = Math.floor(t.y / 8) * MAP.dN + Math.floor(t.x / 8), nm = MAP.dnames[k0], r = atNum(v, 1, 1, 3) | 0; let c = 0; for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) { const cx = Math.floor(t.x / 8) + dx, cy = Math.floor(t.y / 8) + dy; if (cx < 0 || cy < 0 || cx >= MAP.dN || cy >= MAP.dN) continue; const k = cy * MAP.dN + cx; if (MAP.dnames[k] !== nm) { MAP.dnames[k] = nm; c++; } } if (S.p8.world) S.p8.world.cellNames = MAP.dnames.slice(); return '"' + nm + '" grew by ' + c + ' cell(s)'; }, 'grow');
atDef('zoningEditor', 'city', 'Zoning Editor', 'mut', function (v, t) { const z = atNum(v, 1, 0, 9) | 0; return atZone(z)(3, t); }, 'zone paint');
atDef('zoneRes', 'city', 'Residential Zone', 'mut', atZone(1), 'homes');
atDef('zoneCom', 'city', 'Commercial Zone', 'mut', atZone(2), 'shops');
atDef('zoneInd', 'city', 'Industrial Zone', 'mut', atZone(3), 'factories');
atDef('zoneOffice', 'city', 'Office Zone', 'mut', atZone(5), 'business');
atDef('zoneTour', 'city', 'Tourism Zone', 'mut', atZone(6), 'hotels');
atDef('zoneTech', 'city', 'Technology Zone', 'mut', atZone(8), 'tech');
atDef('zonePark', 'city', 'Park Zone', 'mut', function (v, t) { let n = 0; atDisk(t, atNum(v, 3, 1, 8), function (i, x, y) { if (n < 12 && atFree(i) && MAP.nature[i] !== 2 && canPlace(BUILDINGS.park, x, y, true).ok) { const b = makeBuilding('park', x, y); b.owner = 'city'; addBuildingToMap(b); n++; } return false; }); onMapChanged(); return n + ' park tile(s) built'; }, 'green');
atDef('zoneGov', 'city', 'Government Zone', 'mut', atZone(4), 'special services');
atDef('landmarkGen', 'city', 'Landmark Generator', 'mut', function (v, t) { const ids = Object.keys(BUILDINGS).filter(function (k) { return BUILDINGS[k].landmark && BUILDINGS[k].cat === 'Landmarks'; }); const id = BUILDINGS[v] && BUILDINGS[v].landmark ? v : ids[(t.tile + S.buildings.list.length) % ids.length]; const b = atPlace(id, t, 10); return b ? BUILDINGS[id].name + ' placed' : 'No free site for ' + BUILDINGS[id].name; }, 'monument');
atDef('cityCenter', 'city', 'City Center Generator', 'mut', function (v, t) { const out = []; ['plaza', 'park', 'shop', 'restaurant', 'office', 'busstop'].forEach(function (id) { if (BUILDINGS[id] && atPlace(id, t, 5)) out.push(BUILDINGS[id].name); }); return out.length ? 'City centre: ' + out.join(', ') : 'No free space at the target'; }, 'downtown');
atDef('subCenter', 'city', 'Subcenter Generator', 'mut', function (v, t) { const out = []; ['shop', 'school', 'clinic', 'busstop', 'park'].forEach(function (id) { if (BUILDINGS[id] && atPlace(id, t, 6)) out.push(BUILDINGS[id].name); }); return out.length ? 'Subcentre: ' + out.join(', ') : 'No free space at the target'; }, 'local centre');

/* ---------- BUILDINGS (13) ---------- */
atDef('spawnBuilding', 'buildings', 'Spawn Building', 'mut', function (v, t) { const id = BUILDINGS[v] ? v : 'house'; const b = atPlace(id, t, 6); return b ? BUILDINGS[id].name + ' #' + b.id + ' built at ' + b.x + ',' + b.y : 'No free site (VALUE = building id, e.g. house, office, metro)'; }, 'place');
atDef('deleteBuilding', 'buildings', 'Delete Building', 'mut', function (v, t) { if (!t.b) return 'Select a building or centre the camera on one'; if (bdef(t.b).noDemolish) return 'The Town Hall cannot be deleted'; const n = bdef(t.b).name; removeBuilding(t.b); onMapChanged(); return n + ' deleted (Ctrl+Z restores)'; }, 'remove demolish');
atDef('upgradeBuilding', 'buildings', 'Upgrade Building', 'mut', function (v, t) { if (!t.b) return 'No building at the target'; t.b.level = Math.min(MAX_LEVEL, t.b.level + 1); onMapChanged(); return bdef(t.b).name + ' → level ' + t.b.level; });
atDef('repairBuilding', 'buildings', 'Repair Building', 'mut', function (v, t) { const L = t.b ? [t.b] : S.buildings.list; L.forEach(function (b) { b.cond = 100; b.damaged = 0; b.fire = 0; b.closed = false; }); return L.length + ' building(s) repaired'; }, 'fix condition');
atDef('levelEditor', 'buildings', 'Level Editor', 'mut', function (v, t) { if (!t.b) return 'No building at the target'; t.b.level = atNum(v, 3, 1, MAX_LEVEL) | 0; onMapChanged(); return bdef(t.b).name + ' level ' + t.b.level; });
atDef('densityEditor', 'buildings', 'Building Density Editor', 'mut', function (v, t) { const add = atNum(v, 1, -3, 5) | 0; let n = 0; S.buildings.list.forEach(function (b) { if (!bdef(b).housing || Math.abs(b.x - t.x) > 8 || Math.abs(b.y - t.y) > 8) return; b.level = clamp(b.level + add, 1, MAX_LEVEL); n++; }); onMapChanged(); return n + ' home(s) within 8 tiles ' + (add >= 0 ? '+' : '') + add + ' level'; }, 'housing');
atDef('heightEditor', 'buildings', 'Building Height Editor', 'mut', function (v, t) { if (!t.b) return 'No building at the target'; const T = typeof evolveTarget === 'function' ? evolveTarget(t.b) : null; if (!T) return bdef(t.b).name + ' is already its tallest form'; t.b.level = Math.max(t.b.level, 5); const c = evolveCheck(t.b, true); if (!c.ok) return 'Cannot grow: ' + c.reason; if (typeof evolveBuilding === 'function') { evolveBuilding(t.b, true); return 'Grew into ' + T.name; } return 'Evolution not available'; }, 'evolve tower');
atDef('megaBuilding', 'buildings', 'Mega Building Generator', 'mut', function (v, t) { const b = atPlace('megatower', t, 12) || atPlace('megafactory', t, 12); return b ? bdef(b).name + ' placed' : 'No site for a mega building'; });
atDef('megaMall', 'buildings', 'Mega Mall Generator', 'mut', function (v, t) { const b = atPlace('megamall', t, 12); return b ? 'Mega Mall placed' : 'No site for a Mega Mall'; });
atDef('arcology', 'buildings', 'Arcology Generator', 'mut', function (v, t) { const b = atPlace('arcology', t, 12); return b ? 'Arcology placed' : 'No site for an Arcology'; });
atDef('landmarkPlace', 'buildings', 'Landmark Placement', 'mut', function (v, t) { const id = BUILDINGS[v] && BUILDINGS[v].landmark ? v : 'megatower'; const b = atPlace(id, t, 10); return b ? BUILDINGS[id].name + ' placed at ' + b.x + ',' + b.y : 'No site (VALUE = landmark id)'; });
atDef('buildingValidator', 'buildings', 'Building Validator', 'view', function () { const L = S.buildings.list; return atReport({ buildings: L.length, 'not built': L.filter(function (b) { return !b.built; }).length, 'no road': L.filter(function (b) { return !bdef(b).noRoad && b._entry < 0; }).length, unpowered: L.filter(function (b) { return b._powered === false; }).length, 'on fire': L.filter(function (b) { return b.fire > 0; }).length, 'closed': L.filter(function (b) { return b.closed; }).length, 'condition < 40': L.filter(function (b) { return b.cond !== undefined && b.cond < 40; }).length }); }, 'check');
atDef('buildingReplace', 'buildings', 'Building Replacement', 'mut', function (v, t) { if (!t.b || !BUILDINGS[v]) return 'Select a building and give the new building id in VALUE'; const d = BUILDINGS[v], old = t.b, x = old.x, y = old.y; removeBuilding(old); if (!canPlace(d, x, y, true).ok) { addBuildingToMap(old); onMapChanged(); return d.name + ' does not fit there — kept ' + bdef(old).name; } const b = makeBuilding(v, x, y); b.owner = old.owner === 'player' && d.public ? 'city' : old.owner; addBuildingToMap(b); onMapChanged(); return bdef(old).name + ' → ' + d.name; }, 'swap');

/* ---------- UTILITIES (10) ---------- */
atDef('powerGen', 'utilities', 'Power Generator', 'mut', function (v, t) { const id = BUILDINGS[v] && BUILDINGS[v].power > 0 ? v : (hasTech('solar') ? 'solar' : 'powerplant'); const b = atPlace(id, t, 10); return b ? BUILDINGS[id].name + ' built (+' + BUILDINGS[id].power + ' MW)' : 'No site for a generator'; }, 'electricity plant');
atDef('powerRepair', 'utilities', 'Power Grid Repair', 'mut', function () { if (!S.p9) return 'Grid repair needs Part 9 networks'; S.p9.util.failures = []; const r = p9AutoFixUtilities(); return 'Outages cleared · ' + (r || 'grid connected'); }, 'outage substations');
atDef('waterNetGen', 'utilities', 'Water Network Generator', 'mut', function (v, t) { const b = atPlace('waterplant', t, 10) || atPlace('watertower', t, 10); const u = S.p9 ? buildAllUtilities() : []; return (b ? bdef(b).name + ' built · ' : '') + (u.length ? u.join(', ') : 'network complete'); }, 'pumps');
atDef('waterNetRepair', 'utilities', 'Water Network Repair', 'mut', function () { if (S.p9 && S.p9.water) S.p9.water.breaks = []; const r = S.p9 ? p9AutoFixUtilities() : ''; return 'Pipe breaks repaired · ' + (r || 'network OK'); }, 'pipes');
atDef('sewageGen', 'utilities', 'Sewage Generator', 'mut', function (v, t) { const b = atPlace('sewageplant', t, 12); return b ? 'Sewage treatment plant built' : 'No site for a sewage plant'; });
atDef('wasteGen', 'utilities', 'Waste Network Generator', 'mut', function () { const before = S.buildings.list.length; wgAddWaste(null); return (S.buildings.list.length - before) + ' waste facility(ies) added · capacity ' + Math.round(SIM.wasteCap || 0) + ' / production ' + Math.round(SIM.wasteGen || 0); }, 'garbage');
atDef('utilityValidator', 'utilities', 'Utility Validator', 'view', function () { const g = typeof gridStats === 'function' ? gridStats() : {}; return atReport({ 'power ratio': SIM.powerRatio || 0, 'production MW': g.production || SIM.powerGen, 'consumption MW': g.consumption || SIM.powerUse, 'water ratio': SIM.waterRatio || 0, 'low pressure': typeof WNET !== 'undefined' ? WNET.low || 0 : 0, 'sewage overload': typeof SEWER !== 'undefined' ? SEWER.overload || 0 : 0, 'active outages': S.p9 ? S.p9.util.failures.length : 0 }); }, 'check');
atDef('utilityLoad', 'utilities', 'Utility Load Editor', 'mut', function (v) { const k = atNum(v, 1, 0.3, 3), A = atMods(); A.power = k; A.water = k; return 'Power and water demand ×' + k + ' (1 = normal)'; }, 'demand');
atDef('outageSim', 'utilities', 'Outage Simulator', 'mut', function (v, t) { if (!S.p9) return 'Needs Part 9 utility networks'; S.p9.util.failures.push({ x: t.x, y: t.y, r: atNum(v, 5, 1, 20), until: S.clock.runSec + 300, cause: 'admin' }); return 'Power outage around ' + t.x + ',' + t.y + ' for 5 minutes'; }, 'blackout');
atDef('utilityStress', 'utilities', 'Utility Stress Test', 'view', function () { const A = atMods(), keep = [A.power, A.water]; A.power = A.water = 2; econTick(1); const r = { 'power ratio at ×2 demand': SIM.powerRatio, 'water ratio at ×2 demand': SIM.waterRatio }; A.power = keep[0]; A.water = keep[1]; econTick(1); return atReport(r) + '\n(normal demand restored)'; }, 'stress');

/* ---------- POPULATION (11) ---------- */
atDef('popGen', 'population', 'Population Generator', 'mut', function (v) { return admAddPop(atNum(v, 1000, 1, 1e7)) || 'Population +' + v; }, 'citizens add');
atDef('popDensity', 'population', 'Population Density Editor', 'mut', function (v) { econTick(1); const p = atNum(v, 90, 10, 100) / 100; admSetPop(Math.round((SIM.housingCap || 0) * p)); return 'Population set to ' + Math.round(p * 100) + '% of housing (' + fmt(Math.round(S.city.population)) + ')'; }, 'occupancy');
atDef('citizenSpawn', 'population', 'Citizen Spawn', 'mut', function (v) { const n = atNum(v, 10, 1, 200) | 0; let k = 0; for (let i = 0; i < n; i++) if (spawnCitizen(false)) k++; return k + ' citizen agent(s) spawned'; }, 'agent');
atDef('citizenRemove', 'population', 'Citizen Remove', 'mut', function (v) { const n = atNum(v, 10, 1, 500) | 0, before = AG.citizens.length; AG.citizens.splice(Math.max(0, AG.citizens.length - n), n); return (before - AG.citizens.length) + ' citizen agent(s) removed'; }, 'agent');
atDef('householdGen', 'population', 'Household Generator', 'mut', function (v, t) { const n = atNum(v, 4, 1, 30) | 0; let k = 0; for (let i = 0; i < n; i++) if (atPlace('house', t, 10)) k++; return k + ' home(s) built near the target'; }, 'homes housing');
atDef('jobGen', 'population', 'Job Generator', 'mut', function (v, t) { const n = atNum(v, 3, 1, 20) | 0; let k = 0; for (let i = 0; i < n; i++) if (atPlace(i % 2 ? 'shop' : 'office', t, 10)) k++; return k + ' workplace(s) built'; }, 'work employment');
atDef('educationEditor', 'population', 'Education Editor', 'mut', function (v) { S.city.education = atNum(v, 70, 0, 100); AG.citizens.forEach(function (c) { c.edu = clamp(Math.round(S.city.education / 25), 0, 4); }); return 'City education ' + S.city.education + ' · agents set to level ' + Math.round(S.city.education / 25); });
atDef('incomeEditor', 'population', 'Income Editor', 'mut', function (v) { const k = atNum(v, 1, 0.5, 2); atMods().wage = k; return 'Wages ×' + k; }, 'salary');
atDef('ageEditor', 'population', 'Age Distribution Editor', 'mut', function (v) { const d = atNum(v, 5, -30, 30) | 0; AG.citizens.forEach(function (c) { c.age = clamp((c.age || 30) + d, 0, 99); }); return 'All citizen agents ' + (d >= 0 ? 'older' : 'younger') + ' by ' + Math.abs(d) + ' years'; }, 'age');
atDef('migrationSim', 'population', 'Migration Simulator', 'mut', function (v) { const n = atNum(v, 2000, -1e6, 1e6) | 0; admSetPop(Math.max(0, S.city.population + n)); if (S.p10) { if (n > 0) S.p10.pop.migIn += n; else S.p10.pop.migOut -= n; } newsAdd(n > 0 ? '🧳' : '🚚', (n > 0 ? 'MIGRATION IN: ' : 'MIGRATION OUT: ') + fmt(Math.abs(n)) + ' people', 'Admin migration wave.', { cat: 'city' }); return 'Migration ' + (n > 0 ? '+' : '') + fmt(n); }, 'move');
atDef('popValidator', 'population', 'Population Validator', 'view', function () { econTick(1); const homeless = AG.citizens.filter(function (c) { return !c.tourist && !MAP.byId.has(c.home); }).length, nojob = AG.citizens.filter(function (c) { return !c.tourist && !c.work && (c.age || 30) < 67; }).length; return atReport({ population: S.city.population, housing: SIM.housingCap || 0, unemployment: SIM.unemployment || 0, 'agents': AG.citizens.length, 'agents without home': homeless, 'agents without job': nojob }); }, 'check');

/* ---------- ECONOMY (11) ---------- */
atDef('moneyEditor', 'economy', 'Money Editor', 'mut', function (v) { S.money = Math.min(MONEY_CAP, atNum(v, 1e6, 0, MONEY_CAP)); return 'Money = ' + money(S.money); }, 'cash');
atDef('gdpEditor', 'economy', 'GDP Editor', 'mut', function (v) { atMods().gdp = atNum(v, 1, 0.5, 2); return 'Business output ×' + atMods().gdp + ' (GDP follows on the next economic day)'; });
atDef('companyGen', 'economy', 'Company Generator', 'mut', function (v) { if (!S.p17) return 'Needs Economy 2.0'; const secs = ['FOOD', 'SHOPPING', 'TECHNOLOGY', 'FINANCE', 'ENTERTAINMENT', 'INDUSTRY'], n = atNum(v, 3, 1, 50) | 0; for (let i = 0; i < n; i++) { const id = 'adm' + Date.now().toString(36) + i, c = e2NewCo(secs[i % secs.length], 'Admin Co ' + (Object.keys(S.p17.co).length + 1), 1); c.synthetic = true; c.rev = 40; c.cash = 5000; S.p17.co[id] = c; } E2.keys = null; return n + ' compan(ies) founded in the company registry'; }, 'business');
atDef('marketSim', 'economy', 'Market Simulator', 'mut', function () { if (!S.p17) return 'Needs Economy 2.0'; for (let h = 0; h < 24; h++) { S.clock.gameSec += 3600; S.clock.runSec += 3600 / TIME_SCALE; econTick(1); part17Tick(); govTick && govTick(); } return '24 game hours simulated · bread ' + money(e2GoodPrice('bread'), 2) + ' · fuel ' + money(e2GoodPrice('fuel'), 2); }, 'prices day');
atDef('inflationEditor', 'economy', 'Inflation Editor', 'mut', function (v) { S.p6.econ.infl = atNum(v, 2, -5, 25) / 100; return 'Inflation ' + (S.p6.econ.infl * 100).toFixed(1) + '%'; });
atDef('interestEditor', 'economy', 'Interest Editor', 'mut', function (v) { S.p5.econ.rate = Math.max(0.01, atNum(v, 4, 1, 25) / 100); return 'Interest rate ' + (interestRate() * 100).toFixed(2) + '% (floor 1 %)'; }, 'rate');
atDef('tradeSim', 'economy', 'Trade Simulator', 'view', function () { const P = typeof portPass === 'function' ? portPass(0) : { imp: 0, exp: 0 }; return atReport({ 'imports TEU/day': P.imp || 0, 'exports TEU/day': P.exp || 0, 'trade balance/day': S.p17 ? S.p17.gdp.trade : 0, '7-day projection': (S.p17 ? S.p17.gdp.trade : 0) * 7 }); }, 'import export');
atDef('econShock', 'economy', 'Economic Shock', 'mut', function (v) { const id = typeof E2_SHOCKS !== 'undefined' && E2_SHOCKS[v] ? v : 'energy'; const r = e2ShockStart(id, 2, true); return r ? E2_SHOCKS[id].name + ' started' : 'Already active'; }, 'crisis energy food banking');
atDef('recessionSim', 'economy', 'Recession Simulator', 'mut', function () { forceEconPhase('RECESSION'); return 'Economic cycle → RECESSION'; });
atDef('econRecovery', 'economy', 'Economic Recovery', 'mut', function () { forceEconPhase('RECOVERY'); if (S.p17) S.p17.shocks.forEach(function (x) { x.until = S.clock.runSec; }); return 'Cycle → RECOVERY · shocks ending'; });
