/* ---------- One-way roads (pathfinding honours the allowed direction) ---------- */
function tpSetOneWay(tile, dir) { const T = tp().traffic; T.oneway = T.oneway || {}; if (dir) T.oneway[tile] = dir; else delete T.oneway[tile]; tpOneWaySync(); MAP.pathCache.clear(); }
function tpOneWaySync() { if (!MAP.roads) return; const N = MAP.roads.length; if (!MAP.oneway || MAP.oneway.length !== N) MAP.oneway = new Uint8Array(N); else MAP.oneway.fill(0); const O = S && S.transportation && S.transportation.traffic.oneway; if (O) Object.keys(O).forEach(function (k) { if (+k < N && MAP.roads[+k]) MAP.oneway[+k] = O[k]; }); }
(function () { const om = window.onMapChanged; if (typeof om === 'function' && !om.__p19) { window.onMapChanged = function () { const r = om.apply(this, arguments); tpOneWaySync(); return r; }; window.onMapChanged.__p19 = true; } })();

/* ---------- run · undo / redo ---------- */
function atSnap() { try { return JSON.stringify(buildSaveObject()); } catch (e) { return null; } }
function adminTool(id, v) {
  const T = atTool(id); if (!T) return { ok: false, reason: 'Unknown tool' };
  if (!STARTED && T.kind !== 'gen') return { ok: false, reason: 'Start or load a city first' };
  let snap = null; if (T.kind === 'mut') { snap = atSnap(); if (snap) { AT.undo.push({ id: id, name: T.name, s: snap }); if (AT.undo.length > AT.max) AT.undo.shift(); AT.redo = []; } }
  let out; try { out = T.run(v, atTarget()); } catch (e) { out = 'ERROR: ' + (e && e.message); if (typeof logError === 'function') logError('Admin tool ' + id, e && e.message); }
  AT.out = '▶ ' + T.name + '\n' + (out === undefined ? 'done' : String(out)); AT.last = id;
  if (typeof adminLog === 'function') adminLog('🧰 ' + T.name + (v ? ' (' + String(v).slice(0, 30) + ')' : ''));
  return { ok: !/^ERROR/.test(String(out)), msg: String(out).split('\n')[0] };
}
function atRestore(txt) { const slot = S.slot, wasSel = UI.selected; const r = importSave(txt); if (r && r.ok === false) return false; S.slot = slot; void wasSel; UI.selected = null; resetSim(); onMapChanged(); return true; }
function atUndo() { const e = AT.undo.pop(); if (!e) return 'Nothing to undo'; const now = atSnap(); if (now) AT.redo.push({ id: e.id, name: e.name, s: now }); return atRestore(e.s) ? '↶ Undone: ' + e.name : 'Undo failed'; }
function atRedo() { const e = AT.redo.pop(); if (!e) return 'Nothing to redo'; const now = atSnap(); if (now) AT.undo.push({ id: e.id, name: e.name, s: now }); return atRestore(e.s) ? '↷ Redone: ' + e.name : 'Redo failed'; }
if (typeof adminWrap === 'function') { adminWrap('adminTool', function (id) { return 'tool:' + id; }); adminWrap('atUndo', function () { return 'tool:undo'; }); adminWrap('atRedo', function () { return 'tool:redo'; }); }
if (typeof ADMIN_CMD_CAT !== 'undefined') {
  AT_TOOLS.forEach(function (t) { ADMIN_CMD_CAT['tool:' + t.id] = t.kind === 'gen' ? 'generate' : t.kind === 'del' ? 'delete' : t.kind === 'view' ? (t.cat === 'debug' ? 'debug' : 'view') : 'city'; });
  ['perfMonitor', 'memMonitor', 'fpsMonitor', 'entityCounter'].forEach(function (k) { ADMIN_CMD_CAT['tool:' + k] = 'perf'; });
  ADMIN_CMD_CAT['tool:undo'] = ADMIN_CMD_CAT['tool:redo'] = 'city';
}
/* favourites (per device) */
function atFavs() { try { const f = JSON.parse(Store.getItem('bct_admin_fav') || 'null'); return Array.isArray(f) ? f.filter(atTool) : ['createWorld', 'autoFixWorld', 'roadGen', 'metroGen', 'trafficDebugger', 'worldValidator']; } catch (e) { return []; } }
function atToggleFav(id) { const f = atFavs(), i = f.indexOf(id); if (i >= 0) f.splice(i, 1); else if (atTool(id)) f.push(id); try { Store.setItem('bct_admin_fav', JSON.stringify(f.slice(0, 24))); } catch (e) { /* storage */ } }
function atSearch(q) { q = String(q || '').toLowerCase().trim(); if (!q) return []; return AT_TOOLS.filter(function (t) { return (t.name + ' ' + t.kw + ' ' + t.cat).toLowerCase().indexOf(q) >= 0; }); }
